ap=argparse.ArgumentParser();ap.add_argument('--bank',required=True);ap.add_argument('--source',required=True);ap.add_argument('--stage',required=True);args=ap.parse_args();start=time.monotonic();b=ROOT/'.local-models/geometry-workbench/heart';bank=b/args.bank;source=b/args.source;out=b/args.stage;out.mkdir(exist_ok=False);e=json.loads((bank/'emission.json').read_text());z=np.load(bank/'arrangement.npz');p=z['positions'];faces=np.concatenate([z[k]for k in e['surfaces'].values()]);m=Mesh(p,faces,e['frame']);proof,_=self_contact_summary(m,max_pairs=3500000,max_tests=30000000,example_limit=2000);atomic_json(out/'physical-face-audit.json',proof);assert proof['complete_within_pair_budget']and len(proof['examples'])==proof['defect_pairs'];print('Global physical interface defects',proof['defect_pairs'],flush=True);base=np.load(b/'chart-coats-v82/cells.npz')['positions'];o=np.asarray(e['origin']);dtype=np.dtype((np.void,12));protected=np.flatnonzero(np.isin((p-o).astype('<f4').view(dtype).ravel(),(base-o).astype('<f4').view(dtype).ravel()));r=round_diagnosed_crossings(p,faces,proof['examples'],origin=o,protected=protected,seconds=40.,maximum_moves=128,maximum_pair_tests=5000000);atomic_json(out/'rounding.json',r['evidence']);original=np.load(source/'cells.npz');assert np.array_equal(original['positions'],p);arrays={k:original[k]for k in original.files};arrays['positions']=r['positions'];atomic_npz(out/'cells.npz',**arrays);metadata=json.loads((source/'construction.json').read_text());atomic_json(out/'construction.json',dict(metadata,passed=r['evidence']['passed'],source_sha256=digest_file(source/'cells.npz'),names=metadata['names'],rounding=r['evidence'],full_emitted_audits_pending=True,elapsed_seconds=time.monotonic()-start));print(json.dumps(r['evidence']),flush=True)
